import{_ as l,a0 as n,w as d,s as p,I as i,x as e,a1 as o,A as r,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"gedit 深色模式下高亮文本不可见？以下是你能做的 | LCTT x X-CMD","titleTemplate":false,"description":"gedit 深色模式下高亮文本不可见？以下是你能做的 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"gedit 深色模式下高亮文本不可见？以下是你能做的 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"gedit 深色模式下高亮文本不可见？以下是你能做的 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20210120 Highlighted Text Not Visible in gedit in Dark Mode- Here-s What You Can Do","title":"gedit 深色模式下高亮文本不可见？以下是你能做的","tag":"202207","desc":""},"relativePath":"202207/20210120 Highlighted Text Not Visible in gedit in Dark Mode- Here-s What You Can Do.md","filePath":"[post].md"}'),g={name:"202207/20210120 Highlighted Text Not Visible in gedit in Dark Mode- Here-s What You Can Do.md"};function u(m,t,b,f,h,T){const s=n("Link");return d(),p("div",null,[t[24]||(t[24]=i("h1",{id:"gedit-深色模式下高亮文本不可见-以下是你能做的",tabindex:"-1"},[e("gedit 深色模式下高亮文本不可见？以下是你能做的 "),i("a",{class:"header-anchor",href:"#gedit-深色模式下高亮文本不可见-以下是你能做的","aria-label":"Permalink to “gedit 深色模式下高亮文本不可见？以下是你能做的”"},"​")],-1)),t[25]||(t[25]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202207/16/094145b0gdwez5zo0zyuhz.jpg",alt:""})],-1)),i("p",null,[t[1]||(t[1]=e("我喜欢 ",-1)),o(s,{href:"https://itsfoss.com/dark-mode-ubuntu/"},{default:r(()=>[...t[0]||(t[0]=[e("在 Ubuntu 中使用深色模式",-1)])]),_:1}),t[2]||(t[2]=e("。在我看来深色模式能够缓解视觉疲劳，让系统看起来更加的赏心悦目。",-1))]),i("p",null,[t[4]||(t[4]=e("我发现了一个 ",-1)),o(s,{href:"https://wiki.gnome.org/Apps/Gedit"},{default:r(()=>[...t[3]||(t[3]=[e("gedit",-1)])]),_:1}),t[5]||(t[5]=e(" 文本编辑器的小麻烦，如果你在深色模式下使用它，你也许也会遇到。",-1))]),t[26]||(t[26]=a('<p>默认情况下 gedit 高亮当前光标所在的行。这是一个非常有用的功能，但是如果你在 Linux 系统中开启了深色模式，那么你将会感到痛苦。为什么？因为被高亮的文本将不再变得可读。你自己看吧：</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/01/gedit-dark-mode-problem.png?resize=779%2C367&amp;ssl=1" alt="Text on the highlighted line is hardly visible"></p><p>如果你选择文本，它将变得可读，但这并不是一个让人感到有多么愉快的阅读或者编辑体验。（LCTT 校注：在新的 Ubuntu 22.04 中，这一情况已经有所改善，“高亮当前行”已被取消勾选）</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/01/gedit-dark-mode-issue.png?resize=779%2C367&amp;ssl=1" alt="Selecting the text makes it better but that’s not a convenient thing to do for all lines"></p><p>好消息是你不需要再忍受它。我将演示几个步骤让你能够同时享受 gedit 以及系统的深色模式。</p><h3 id="让-gedit-在深色模式下阅读体验友好" tabindex="-1">让 gedit 在深色模式下阅读体验友好 <a class="header-anchor" href="#让-gedit-在深色模式下阅读体验友好" aria-label="Permalink to “让 gedit 在深色模式下阅读体验友好”">​</a></h3><p>你基本上有两个选择：</p><ol><li>禁用高亮当前行，但也同时意味着你必须清楚地知道你在哪一行。</li><li>改变默认的颜色设置，但编辑器的颜色会变得稍微有些不同，而且如果你更改系统主题，它不会自动切换到浅色模式。</li></ol><p>在 gedit 或者 GNOME 的开发者解决这个问题之前，这是你必须要做的应变和妥协。</p><h4 id="选项1-禁止高亮当前行" tabindex="-1">选项1： 禁止高亮当前行 <a class="header-anchor" href="#选项1-禁止高亮当前行" aria-label="Permalink to “选项1： 禁止高亮当前行”">​</a></h4><p>当你打开 gedit 后，点击汉堡菜单然后选择“<ruby>首选项<rt>Preferences</rt></ruby>”。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/01/gedit-preference.jpg?resize=777%2C527&amp;ssl=1" alt="Go to Preferences"></p><p>在查看选项卡，你应该看到在 “<ruby>高亮<rt>Highlighting</rt></ruby>” 区域的下方的 “<ruby>高亮当前行<rt>Highlight current line</rt></ruby>” 选项。取消勾选这个选项，马上就可以看到效果。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/01/disable-highlight-line-gedit.jpg?resize=781%2C530&amp;ssl=1" alt="Disable highlighting current line"></p><p>“高亮当前行”是一个有用的功能，如果你想继续使用它，请选择第二个选项。</p><h4 id="选项2-更改编辑器的颜色主题" tabindex="-1">选项2： 更改编辑器的颜色主题 <a class="header-anchor" href="#选项2-更改编辑器的颜色主题" aria-label="Permalink to “选项2： 更改编辑器的颜色主题”">​</a></h4><p>在“<ruby>首选项<rt>Preferences</rt></ruby>”窗口，找到 “<ruby>字体与颜色<rt>Font &amp; Colors</rt></ruby>” 标签页，然后将颜色主题更改为 “Oblivion”、“Solarized Dark”，或者 “Cobalt”。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/01/change-color-scheme-gedit.jpg?resize=785%2C539&amp;ssl=1" alt="Change the color scheme"></p><p>正如我前面所提到的，缺点就是当你把系统主题切换为浅色模式时，编辑器将不会自动切换到浅色模式。</p><h3 id="开发者应该修复的一个-bug" tabindex="-1">开发者应该修复的一个 bug <a class="header-anchor" href="#开发者应该修复的一个-bug" aria-label="Permalink to “开发者应该修复的一个 bug”">​</a></h3>',20)),i("p",null,[t[7]||(t[7]=e("这里 ",-1)),o(s,{href:"https://itsfoss.com/best-modern-open-source-code-editors-for-linux/"},{default:r(()=>[...t[6]||(t[6]=[e("有几个 Linux 可用的文本编辑器",-1)])]),_:1}),t[8]||(t[8]=e(" ，但是为了快速阅读或编辑文本文件，我更推荐使用 gedit。尽管如此，小烦恼仍旧是小烦恼。开发者应该在将来的版本中为这个很好的文本编辑器修复这个问题，让我们不再求助于这些应对办法。",-1))]),t[27]||(t[27]=i("p",null,"你呢？你在你的系统上使用深色模式还是浅色模式？你注意到 gedit 的这个问题了吗？你有使用什么方法去解决它吗？欢迎分享你的经验。",-1)),t[28]||(t[28]=i("hr",null,null,-1)),i("p",null,[t[10]||(t[10]=e("via: ",-1)),o(s,{href:"https://itsfoss.com/gedit-dark-mode-problem/"},{default:r(()=>[...t[9]||(t[9]=[e("https://itsfoss.com/gedit-dark-mode-problem/",-1)])]),_:1})]),i("p",null,[t[15]||(t[15]=e("作者：",-1)),o(s,{href:"https://itsfoss.com/author/abhishek/"},{default:r(()=>[...t[11]||(t[11]=[e("Abhishek Prakash",-1)])]),_:1}),t[16]||(t[16]=e(" 选题：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[12]||(t[12]=[e("lujun9972",-1)])]),_:1}),t[17]||(t[17]=e(" 译者：",-1)),o(s,{href:"https://github.com/void-mori"},{default:r(()=>[...t[13]||(t[13]=[e("void-mori",-1)])]),_:1}),t[18]||(t[18]=e(" 校对：",-1)),o(s,{href:"https://github.com/wxy"},{default:r(()=>[...t[14]||(t[14]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[21]||(t[21]=e("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[19]||(t[19]=[e("LCTT",-1)])]),_:1}),t[22]||(t[22]=e(" 原创编译，",-1)),o(s,{href:"https://linux.cn/"},{default:r(()=>[...t[20]||(t[20]=[e("Linux中国",-1)])]),_:1}),t[23]||(t[23]=e(" 荣誉推出",-1))])])}const w=l(g,[["render",u]]);export{k as __pageData,w as default};
